+//! Reuse typed validation for visible children without constructing parent defaults.
+
+use super::{NativeExecutionContext, ReservedVec, Result, check};
+use vortex::array::dtype::{DType, PType};
+
+pub(in crate::local_primitives::native_payload) fn observed_rows(
+    rows: &[Option<usize>],
+    dtype: &DType,
+    context: &NativeExecutionContext<'_>,
+) -> Result<Option<ReservedVec<Option<usize>>>> {
+    let admitted = matches!(dtype, DType::Bool(_) | DType::Utf8(_) | DType::Binary(_))
+        || matches!(dtype, DType::Primitive(ptype, _) if *ptype != PType::F16)
+        || crate::native_payload_schema::temporal_storage(dtype).is_some();
+    if !admitted || rows.iter().all(Option::is_some) {
+        return Ok(None);
+    }
+    if matches!(dtype, DType::Utf8(_)) && rows.iter().any(Option::is_some) {
+        // UTF-8 execution diagnostics can name the selected row position.
+        // Preserve those positions and the original scalar validation path,
+        // including nullable text, whenever any observed value remains.
+        return Ok(None);
+    }
+    let count = rows.iter().flatten().count();
+    let mut observed = ReservedVec::new(context.memory())?;
+    observed.reserve(count)?;
+    for (row, index) in rows.iter().enumerate() {
+        check(row, context)?;
+        if index.is_some() {
+            observed.values.push(*index);
+        }
+    }
+    // These leaves use valid zero/empty defaults for absent parent coordinates.
+    // Those defaults contribute no errors or variable bytes. Observed values
+    // keep their order and multiplicity, and selection still precedes execution.
+    #[cfg(all(test, debug_assertions))]
+    super::super::super::native_relational_observation::record(|counts| {
+        counts.payload_selected_validation_columns += 1;
+        counts.payload_selected_validation_rows += count as u64;
+        counts.payload_selected_validation_absent_rows += (rows.len() - count) as u64;
+    });
+    Ok(Some(observed))
+}

