+//! Bind canonical decimal buffers once while retaining Vortex's exact validator.
+
+use super::{NativeExecutionContext, Result, check, vortex_error};
+use vortex::array::{
+    ArrayRef, ExecutionCtx,
+    arrays::{Bool, Decimal, decimal::DecimalArrayExt as _},
+    dtype::DType,
+    scalar::{DecimalValue, Scalar, ScalarValue},
+    validity::Validity,
+};
+
+pub(in crate::local_primitives::native_payload) fn validate(
+    source: Option<&ArrayRef>,
+    rows: &[Option<usize>],
+    dtype: &DType,
+    execution: &mut ExecutionCtx,
+    context: &NativeExecutionContext<'_>,
+) -> Result<bool> {
+    let DType::Decimal(decimal, _) = dtype else {
+        return Ok(false);
+    };
+    let Some(source) = source else {
+        return Ok(false);
+    };
+    if !crate::native_payload_schema::admitted_decimal(*decimal)
+        || source.dtype() != dtype
+        || !source.is_host()
+    {
+        return Ok(false);
+    }
+    let Some(array) = source.as_opt::<Decimal>() else {
+        return Ok(false);
+    };
+    let validity = array.validity().map_err(vortex_error)?;
+    // Executing an encoded mask in full can observe an unselected invalid code
+    // or change which failure is reported first. Bind only intrinsic masks;
+    // other validity owners retain the existing ordered per-row resolver.
+    if let Validity::Array(mask) = &validity
+        && (!mask.is::<Bool>() || !mask.is_host() || mask.dtype().is_nullable())
+    {
+        return Ok(false);
+    }
+    let valid = validity
+        .execute_mask(array.len(), execution)
+        .map_err(vortex_error)?;
+    vortex::array::match_each_decimal_value_type!(array.values_type(), |D| {
+        let values = array.buffer::<D>();
+        for (row, original) in rows.iter().enumerate() {
+            check(row, context)?;
+            let value = if let Some(original) = original {
+                if *original >= values.len() {
+                    return Err(super::super::failed(
+                        "private decimal index exceeds its native owner",
+                    ));
+                }
+                valid
+                    .value(*original)
+                    .then(|| ScalarValue::Decimal(DecimalValue::from(values[*original])))
+            } else if dtype.is_nullable() {
+                None
+            } else {
+                Some(ScalarValue::Decimal(DecimalValue::I128(0)))
+            };
+            Scalar::validate(dtype, value.as_ref()).map_err(vortex_error)?;
+        }
+    });
+    #[cfg(all(test, debug_assertions))]
+    super::super::super::native_relational_observation::record(|counts| {
+        counts.payload_decimal_validation_columns += 1;
+        counts.payload_decimal_validation_rows += rows.len() as u64;
+    });
+    Ok(true)
+}

