+#[test]
+fn selected_payload_validation_respects_memory_refusal_and_decimal_cancellation() {
+    let session = ResidentVortexSession::new(1 << 20, 1).unwrap();
+    let cancellation = CancellationToken::default();
+    let result = session.with_native_execution_context(&cancellation, |context| {
+        let baseline = context.memory().snapshot().reserved_bytes;
+        let held = context.memory().reserve((1 << 20) - baseline)?;
+        let dtype = DType::Primitive(PType::I64, Nullability::NonNullable);
+        assert!(validation::observed_rows(&[None, Some(1)], &dtype, context).is_err());
+        let source = DecimalArray::try_new(
+            Buffer::from(vec![7_i128; 2053]),
+            DecimalDType::new(2, 0),
+            Validity::NonNullable,
+        )
+        .unwrap()
+        .into_array();
+        let rows = (0..source.len()).map(Some).collect::<Vec<_>>();
+        let mut execution = context.native_session().create_execution_ctx();
+        assert!(validation::validate_decimal(
+            Some(&source),
+            &rows,
+            source.dtype(),
+            &mut execution,
+            context
+        )?);
+        assert_eq!(context.memory().snapshot().reserved_bytes, 1 << 20);
+        drop(held);
+        cancellation.cancel();
+        let error = validation::validate_decimal(
+            Some(&source),
+            &rows,
+            source.dtype(),
+            &mut execution,
+            context,
+        )
+        .unwrap_err();
+        assert!(error.to_string().contains("cancel"));
+        assert_eq!(context.memory().snapshot().reserved_bytes, baseline);
+        Ok(())
+    });
+    assert!(result.unwrap_err().to_string().contains("cancel"));
+    assert_eq!(session.memory().snapshot().reserved_bytes, 0);
+}
